mapper.update:
update coop_settlement
status = #{status}, payout_time = #{payoutTime}, amount = #{amount},
where id = #{id}

update coop_settlement
set status = 1, payout_time = #{payoutTime}
where id = #{id} and del_flag = 0 and status = 0

mapper.select:
select  from coop_settlement
where del_flag = 0 and merchant_id = #{merchantId}
order by create_time desc

select  from coop_settlement
where del_flag = 0 and beneficiary_role = #{role} and beneficiary_id = #{beneficiaryId}
order by create_time desc

select  from coop_settlement
where del_flag = 0 and topic_id = #{topicId}
order by create_time desc

select count(1) from coop_settlement
where del_flag = 0 and status = 1
  and topic_id = #{topicId} and merchant_id = #{payeeId}
